        var trimmed = decoded.Trim();

        if (trimmed.Length == 0)
        {
            return string.Empty;
        }

        var lowered = trimmed.ToLowerInvariant();
        var hyphenated = Regex.Replace(lowered, "\\s+", "-", RegexOptions.Compiled);
        return Uri.EscapeDataString(hyphenated);
    }
}

