            }

            var normalized = Regex.Replace(attrs, "style=\"(?<style>[^\"]*)\"", styleMatch =>
            {
                var style = styleMatch.Groups["style"].Value.Trim();
                style = style.TrimEnd(';');
                return $"style=\"{style}\"";
            }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

            return $"<details{(normalized.StartsWith(' ') ? string.Empty : " ")}{normalized}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Adds Azure DevOps-like display and whitespace styles to inline diff code and span elements.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with normalized inline diff styles.</returns>
    private static string NormalizeAzdoDiffInlineStyles(string html)
    {
        var withCodeStyles = Regex.Replace(html, "<code\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
        {
            var style = match.Groups["style"].Value;
            style = EnsureStyleDirective(style, "display:block");
            style = EnsureStyleDirective(style, "white-space:normal");
            style = EnsureStyleDirective(style, "padding:0");
            style = EnsureStyleDirective(style, "margin:0");
            return $"<code style=\"{style}\"{match.Groups["rest"].Value}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

        var withSpanStyles = Regex.Replace(withCodeStyles, "<span\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
        {
            var style = match.Groups["style"].Value;
            if (style.Contains("border-left", StringComparison.OrdinalIgnoreCase) || style.Contains("background-color", StringComparison.OrdinalIgnoreCase))
            {
                style = EnsureStyleDirective(style, "display:inline-block");
            }

            return $"<span style=\"{style}\"{match.Groups["rest"].Value}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

        return withSpanStyles;
    }

    /// <summary>
    /// Appends a CSS directive to a style string when it is not already present.
    /// </summary>
    /// <param name="style">Existing style string.</param>
    /// <param name="directive">Directive to enforce.</param>
    /// <returns>Updated style string.</returns>
    private static string EnsureStyleDirective(string style, string directive)
    {
        if (string.IsNullOrWhiteSpace(style))
        {
            return directive;
        }

        if (style.Contains(directive, StringComparison.OrdinalIgnoreCase))
        {
            return style;
        }

        return style.TrimEnd().EndsWith(';') ? $"{style} {directive}" : $"{style}; {directive}";
    }

    /// <summary>
    /// Builds a slug from heading content that preserves emoji and punctuation before prefixing.
    /// </summary>
    /// <param name="headingContent">Inner HTML of the heading.</param>
    /// <returns>URL-encoded slug derived from the heading text.</returns>
    private static string CreateSlug(string headingContent)
    {
        if (string.IsNullOrWhiteSpace(headingContent))
        {
            return string.Empty;
        }

        var withBackticks = Regex.Replace(headingContent, "<code>(.*?)</code>", match => $"`{match.Groups[1].Value}`", RegexOptions.Singleline | RegexOptions.IgnoreCase | RegexOptions.Compiled);
        var withoutTags = Regex.Replace(withBackticks, "<.*?>", string.Empty, RegexOptions.Singleline | RegexOptions.Compiled);
        var decoded = WebUtility.HtmlDecode(withoutTags);
        var trimmed = decoded.Trim();

        if (trimmed.Length == 0)
        {
            return string.Empty;
        }

        var lowered = trimmed.ToLowerInvariant();
        var hyphenated = Regex.Replace(lowered, "\\s+", "-", RegexOptions.Compiled);
        return Uri.EscapeDataString(hyphenated);
    }
}

using System.Text.RegularExpressions;
using Oocx.TfPlan2Md.HtmlRenderer;
using Oocx.TfPlan2Md.HtmlRenderer.Rendering;

namespace Oocx.TfPlan2Md.HtmlRenderer.Tests;

/// <summary>
/// Validates the core markdown-to-HTML rendering behavior.
/// Related feature: docs/features/027-markdown-html-rendering/specification.md
/// </summary>
public sealed class MarkdownToHtmlRendererTests
{
    /// <summary>
    /// Ensures tables and details/summary blocks are rendered into the expected HTML elements.
    /// Related acceptance: Task 3 (tables, details support).
    /// </summary>
    [Fact]
    public void RenderFragment_TablesAndDetails_RendersExpectedElements()
    {
        const string markdown = """
# Heading

| Col1 | Col2 |
| --- | ---: |
| a | b |

<details><summary>More</summary>Body</details>
""";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.GitHub);

        Assert.Contains("<table>", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("<details>", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("<summary>More</summary>", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("<th", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures GitHub flavor wraps tables with the platform accessibility element and role attribute.
    /// Related acceptance: Feature 027 GitHub fidelity.
    /// </summary>
    [Fact]
    public void RenderFragment_GitHub_WrapsTablesForAccessibility()
    {
        const string markdown = """
| A | B |
| - | - |
| 1 | 2 |
""";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.GitHub);

        Assert.Contains("<markdown-accessiblity-table", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("role=\"table\"", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures fenced code blocks emit language classes compatible with syntax highlighting libraries.
    /// Related acceptance: Task 3 (code blocks with language class) and TC-08.
    /// </summary>
    [Fact]
    public void RenderFragment_CodeBlock_IncludesLanguageClass()
    {
        const string markdown = """
```diff
- old
+ new
```
""";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.AzureDevOps);

        Assert.Contains("<code class=\"language-diff\"", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("<pre>", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures GitHub flavor strips style attributes from inline HTML to match sanitization.
    /// Related acceptance: TC-05.
    /// </summary>
    [Fact]
    public void RenderFragment_GitHub_StripsStyleAttributes()
    {
        const string markdown = "<span style=\"color:red\">text</span>";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.GitHub);

        Assert.DoesNotContain("style=", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("<span", html, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("<span >", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures Azure DevOps flavor preserves style attributes used by inline diff rendering.
    /// Related acceptance: TC-06.
    /// </summary>
    [Fact]
    public void RenderFragment_AzDo_PreservesStyleAttributes()
    {
        const string markdown = "<span style=\"color:red\">text</span>";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.AzureDevOps);

        Assert.Contains("style=\"color:red\"", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures Azure DevOps flavor applies block and inline-block styling to inline diff code/spans for fidelity.
    /// Related acceptance: Feature 027 Azure DevOps cosmetics.
    /// </summary>
    [Fact]
    public void RenderFragment_AzDo_AddsDiffDisplayStyles()
    {
        const string markdown = "<code style=\"color:red\"><span style=\"background-color: #fff5f5; border-left: 3px solid #d73a49; color: #24292e; padding-left: 8px; margin-left: 0\">- old</span></code>";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.AzureDevOps);

        Assert.Contains("display:block", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("display:inline-block", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures trailing semicolons in style attributes are trimmed during normalization.
    /// Related acceptance: Feature 027 Azure DevOps cosmetics.
    /// </summary>
    [Fact]
    public void RenderFragment_AzDo_TrimsTrailingSemicolons()
    {
        const string markdown = "<code style=\"padding:0; margin:0; \" aria-label=\"removed\">value</code>";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.AzureDevOps);

        var match = Regex.Match(html, "style=\"([^\"]*)\"", RegexOptions.IgnoreCase);
        Assert.True(match.Success);
        Assert.False(match.Groups[1].Value.Trim().EndsWith(';', StringComparison.Ordinal));
    }

    /// <summary>
    /// Ensures Azure DevOps flavor keeps single newlines as soft breaks while honoring hard breaks (two spaces).
    /// Related acceptance: TC-07.
    /// </summary>
    [Fact]
    public void RenderFragment_AzDo_LineBreaksRespectTwoSpaces()
    {
        const string markdown = """
Line 1
Line 2
Line 3  
Line 4
""";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.AzureDevOps);

        Assert.DoesNotContain("Line 1<br", html, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("Line 2<br", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("Line 3", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("Line 4", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("<br", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures inline HTML such as &lt;br/&gt; is preserved in the output, aligning with tfplan2md reports.
    /// Related acceptance: Task 3 (inline HTML support).
    /// </summary>
    [Fact]
    public void RenderFragment_PreservesInlineHtml()
    {
        const string markdown = "Value<br/>Next";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.GitHub);

        Assert.Contains("<br/>", html, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("Value", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Ensures emoji and backtick content in headings produce percent-encoded slugs matching platform patterns.
    /// Related acceptance: Feature 027 heading id fidelity.
    /// </summary>
    [Fact]
    public void RenderFragment_AzDo_EmojiHeadingSlugMatchesPattern()
    {
        const string markdown = "### 📦 Module: `module.network`";

        var renderer = CreateRenderer();
        var html = renderer.RenderFragment(markdown, HtmlFlavor.AzureDevOps);

        Assert.Contains("id=\"user-content-%F0%9F%93%A6-module%3A-%60module.network%60\"", html, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Creates the renderer with a default pipeline factory for tests.
    /// </summary>
    /// <returns>An initialized <see cref="MarkdownToHtmlRenderer"/> instance.</returns>
    private static MarkdownToHtmlRenderer CreateRenderer()
    {
        var factory = new MarkdigPipelineFactory();
        return new MarkdownToHtmlRenderer(factory);
    }
}

using System.Net;
using System.Text.RegularExpressions;
using Markdig;

namespace Oocx.TfPlan2Md.HtmlRenderer.Rendering;

/// <summary>
/// Converts Markdown content into HTML fragments using Markdig.
/// Related feature: docs/features/027-markdown-html-rendering/specification.md
/// </summary>
internal sealed class MarkdownToHtmlRenderer
{
    /// <summary>
    /// Matches inline style attributes so GitHub flavor output mirrors platform sanitization rules.
    /// Related feature: docs/features/027-markdown-html-rendering/specification.md
    /// </summary>
    private static readonly Regex StyleRegex = new("(\\s)style\\s*=\\s*\"[^\"]*\"|(\\s)style\\s*=\\s*'[^']*'", RegexOptions.IgnoreCase | RegexOptions.Compiled);

    /// <summary>
    /// Provides the Markdig pipeline instances for rendering.
    /// Related feature: docs/features/027-markdown-html-rendering/specification.md
    /// </summary>
    private readonly MarkdigPipelineFactory _pipelineFactory;

    /// <summary>
    /// Initializes a new instance of the <see cref="MarkdownToHtmlRenderer"/> class.
    /// </summary>
    /// <param name="pipelineFactory">Factory that builds Markdig pipelines per flavor.</param>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="pipelineFactory"/> is null.</exception>
    public MarkdownToHtmlRenderer(MarkdigPipelineFactory pipelineFactory)
    {
        _pipelineFactory = pipelineFactory ?? throw new ArgumentNullException(nameof(pipelineFactory));
    }

    /// <summary>
    /// Renders Markdown into an HTML fragment appropriate for the selected flavor.
    /// </summary>
    /// <param name="markdown">Markdown input to render.</param>
    /// <param name="flavor">Target rendering flavor.</param>
    /// <returns>HTML fragment output.</returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="markdown"/> is null.</exception>
    public string RenderFragment(string markdown, HtmlFlavor flavor)
    {
        ArgumentNullException.ThrowIfNull(markdown);

        var pipeline = _pipelineFactory.Create(flavor);
        var document = Markdown.Parse(markdown, pipeline);
        var html = Markdown.ToHtml(document, pipeline);

        return PostProcess(html, flavor);
    }

    /// <summary>
    /// Strips style attributes from rendered HTML to mimic GitHub sanitization.
    /// </summary>
    /// <param name="html">HTML fragment to sanitize.</param>
    /// <returns>Sanitized HTML without inline style attributes.</returns>
    private static string RemoveStyleAttributes(string html)
    {
        if (string.IsNullOrEmpty(html))
        {
            return html;
        }

        return StyleRegex.Replace(html, match => match.Groups[1].Success ? match.Groups[1].Value : match.Groups[2].Value);
    }

    /// <summary>
    /// Applies flavor-specific post-processing including sanitization and attribute alignment.
    /// Related feature: docs/features/027-markdown-html-rendering/specification.md
    /// </summary>
    /// <param name="html">Rendered HTML fragment.</param>
    /// <param name="flavor">Target flavor.</param>
    /// <returns>Adjusted HTML fragment.</returns>
    private static string PostProcess(string html, HtmlFlavor flavor)
    {
        if (string.IsNullOrEmpty(html))
        {
            return html;
        }

        var withNormalizedBreaks = NormalizeBreakTags(html);
        var withNormalizedRules = NormalizeHorizontalRuleTags(withNormalizedBreaks);
        var withNbsp = ReplaceNonBreakingSpaces(withNormalizedRules);

        if (flavor == HtmlFlavor.GitHub)
        {
            var withDirection = AddDirAuto(withNbsp);
            var withWrappedTables = WrapTablesForGitHub(withDirection);
            var withNotranslate = AddNotranslateToCode(withWrappedTables);
            var withoutIds = RemoveHeadingIds(withNotranslate);
            var withoutStyles = RemoveStyleAttributes(withoutIds);
            return CollapseDanglingTagWhitespace(withoutStyles);
        }

        var withNormalizedDetails = NormalizeDetailsTags(withNbsp);
        var withDiffStyles = NormalizeAzdoDiffInlineStyles(withNormalizedDetails);
        var withTrimmedStyles = TrimTrailingSemicolons(withDiffStyles);
        var withPrefixedIds = RewriteHeadingIdsWithPrefix(withTrimmedStyles, "user-content-");
        return withPrefixedIds;
    }

    /// <summary>
    /// Adds dir="auto" to headings and paragraphs when missing to mirror platform output.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with dir attributes on headings and paragraphs.</returns>
    private static string AddDirAuto(string html)
    {
        return Regex.Replace(html, "<(h[1-6]|p)(?=[\\s>])([^>]*)>", match =>
        {
            var tagName = match.Groups[1].Value;
            var attributes = match.Groups[2].Value;
            if (Regex.IsMatch(attributes, "\\sdir=", RegexOptions.IgnoreCase))
            {
                return match.Value;
            }

            return $"<{tagName} dir=\"auto\"{attributes}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Removes heading id attributes to align with GitHub rendering where ids are absent.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML without heading ids.</returns>
    private static string RemoveHeadingIds(string html)
    {
        return Regex.Replace(html, "<(h[1-6])(.*?)\\sid=\".*?\"(.*?)>", "<$1$2$3>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Prefixes heading id attributes to approximate Azure DevOps / GitHub user-content ids.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <param name="prefix">Prefix to apply to existing ids.</param>
    /// <returns>HTML with prefixed heading ids.</returns>
    private static string RewriteHeadingIdsWithPrefix(string html, string prefix)
    {
        return Regex.Replace(html, "<(h[1-6])([^>]*)>(.*?)</\\1>", match =>
        {
            var tag = match.Groups[1].Value;
            var attributes = match.Groups[2].Value;
            var content = match.Groups[3].Value;
            var slug = CreateSlug(content);
            if (string.IsNullOrEmpty(slug))
            {
                return match.Value;
            }

            var withoutExistingId = Regex.Replace(attributes, "\\sid=\".*?\"", string.Empty, RegexOptions.IgnoreCase | RegexOptions.Compiled);
            return $"<{tag}{withoutExistingId} id=\"{prefix}{slug}\">{content}</{tag}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
    }

    /// <summary>
    /// Replaces non-breaking space characters with HTML entities for clarity and alignment with references.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with explicit &amp;nbsp; entities.</returns>
    private static string ReplaceNonBreakingSpaces(string html)
    {
        return html.Replace("\u00A0", "&nbsp;", StringComparison.Ordinal);
    }

    /// <summary>
    /// Wraps tables with GitHub's accessibility helper and assigns role attributes to mirror recorded output.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with wrapped tables for GitHub fidelity.</returns>
    private static string WrapTablesForGitHub(string html)
    {
        return Regex.Replace(html, "<table(?<attrs>[^>]*)>(?<body>.*?)</table>", match =>
        {
            if (match.Value.Contains("markdown-accessiblity-table", StringComparison.OrdinalIgnoreCase))
            {
                return match.Value;
            }

            var attributes = match.Groups["attrs"].Value;
            if (!Regex.IsMatch(attributes, "\\srole=", RegexOptions.IgnoreCase))
            {
                attributes = $"{attributes} role=\"table\"";
            }

            if (!Regex.IsMatch(attributes, "\\stabindex=", RegexOptions.IgnoreCase))
            {
                attributes = $"{attributes} tabindex=\"0\"";
            }

            return $"<markdown-accessiblity-table data-catalyst=\"\"><table{attributes}>{match.Groups["body"].Value}</table></markdown-accessiblity-table>";
        }, RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
    }

    /// <summary>
    /// Normalizes line break tags to self-closing form for consistent comparisons.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with canonical <br/> tags.</returns>
    private static string NormalizeBreakTags(string html)
    {
        return Regex.Replace(html, "<br\\s*/?>", "<br/>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Normalizes horizontal rule tags to self-closing form for consistent comparisons.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with canonical <hr/> tags.</returns>
    private static string NormalizeHorizontalRuleTags(string html)
    {
        return Regex.Replace(html, "<hr\\s*/?>", "<hr/>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Adds GitHub-style notranslate classes to code elements to mirror platform rendering.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with notranslate applied to code tags.</returns>
    private static string AddNotranslateToCode(string html)
    {
        return Regex.Replace(html, "<code(?<attrs>[^>]*)>", match =>
        {
            var attributes = match.Groups["attrs"].Value;
            if (Regex.IsMatch(attributes, "notranslate", RegexOptions.IgnoreCase))
            {
                return match.Value;
            }

            var classMatch = Regex.Match(attributes, "\\bclass\\s*=\\s*([\"'])(.*?)\\1", RegexOptions.IgnoreCase | RegexOptions.Compiled);
            if (classMatch.Success)
            {
                var beforeClass = attributes[..classMatch.Index];
                var afterClass = attributes[(classMatch.Index + classMatch.Length)..];
                var quote = classMatch.Groups[1].Value;
                var classes = $"{classMatch.Groups[2].Value} notranslate".Trim();
                return $"<code{beforeClass} class={quote}{classes}{quote}{afterClass}>";
            }

            return $"<code class=\"notranslate\"{attributes}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Removes dangling whitespace before tag closures introduced by attribute stripping.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with compact tag delimiters.</returns>
    private static string CollapseDanglingTagWhitespace(string html)
    {
        return Regex.Replace(html, "<(\\w+)\\s+>", "<$1>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Trims trailing semicolons in style attributes to mirror platform normalization.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with trimmed style declarations.</returns>
    private static string TrimTrailingSemicolons(string html)
    {
        return Regex.Replace(html, "style=\"(?<style>[^\"]*?)\"", match =>
        {
            var style = match.Groups["style"].Value.Trim();
            style = style.TrimEnd(';');
            return $"style=\"{style}\"";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Normalizes details tags by trimming trailing style semicolons and removing stray spaces for closer platform output.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with normalized details tags.</returns>
    private static string NormalizeDetailsTags(string html)
    {
        return Regex.Replace(html, "<details(?<attrs>[^>]*)>", match =>
        {
            var attrs = match.Groups["attrs"].Value.Trim();
            if (string.IsNullOrEmpty(attrs))
            {
                return "<details>";
            }

            var normalized = Regex.Replace(attrs, "style=\"(?<style>[^\"]*)\"", styleMatch =>
            {
                var style = styleMatch.Groups["style"].Value.Trim();
                style = style.TrimEnd(';');
                return $"style=\"{style}\"";
            }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

            return $"<details{(normalized.StartsWith(' ') ? string.Empty : " ")}{normalized}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Adds Azure DevOps-like display and whitespace styles to inline diff code and span elements.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with normalized inline diff styles.</returns>
    private static string NormalizeAzdoDiffInlineStyles(string html)
    {
        var withCodeStyles = Regex.Replace(html, "<code\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
        {
            var style = match.Groups["style"].Value;
            style = EnsureStyleDirective(style, "display:block");
            style = EnsureStyleDirective(style, "white-space:normal");
            style = EnsureStyleDirective(style, "padding:0");
            style = EnsureStyleDirective(style, "margin:0");
            return $"<code style=\"{style}\"{match.Groups["rest"].Value}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

        var withSpanStyles = Regex.Replace(withCodeStyles, "<span\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
        {
            var style = match.Groups["style"].Value;
            if (style.Contains("border-left", StringComparison.OrdinalIgnoreCase) || style.Contains("background-color", StringComparison.OrdinalIgnoreCase))
            {
                style = EnsureStyleDirective(style, "display:inline-block");
            }

            return $"<span style=\"{style}\"{match.Groups["rest"].Value}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

        return withSpanStyles;
    }

    /// <summary>
    /// Appends a CSS directive to a style string when it is not already present.
    /// </summary>
    /// <param name="style">Existing style string.</param>
    /// <param name="directive">Directive to enforce.</param>
    /// <returns>Updated style string.</returns>
    private static string EnsureStyleDirective(string style, string directive)
    {
        if (string.IsNullOrWhiteSpace(style))
        {
            return directive;
        }

        if (style.Contains(directive, StringComparison.OrdinalIgnoreCase))
        {
            return style;
        }

        return style.TrimEnd().EndsWith(';') ? $"{style} {directive}" : $"{style}; {directive}";
    }

    /// <summary>
    /// Builds a slug from heading content that preserves emoji and punctuation before prefixing.
    /// </summary>
    /// <param name="headingContent">Inner HTML of the heading.</param>
    /// <returns>URL-encoded slug derived from the heading text.</returns>
    private static string CreateSlug(string headingContent)
    {
        if (string.IsNullOrWhiteSpace(headingContent))
        {
            return string.Empty;
        }

        var withBackticks = Regex.Replace(headingContent, "<code>(.*?)</code>", match => $"`{match.Groups[1].Value}`", RegexOptions.Singleline | RegexOptions.IgnoreCase | RegexOptions.Compiled);
        var withoutTags = Regex.Replace(withBackticks, "<.*?>", string.Empty, RegexOptions.Singleline | RegexOptions.Compiled);
        var decoded = WebUtility.HtmlDecode(withoutTags);
        var trimmed = decoded.Trim();

        if (trimmed.Length == 0)
        {
            return string.Empty;
        }

        var lowered = trimmed.ToLowerInvariant();
        var hyphenated = Regex.Replace(lowered, "\\s+", "-", RegexOptions.Compiled);
        return Uri.EscapeDataString(hyphenated);
    }
}

using System.Net;
using System.Text.RegularExpressions;
using Markdig;

namespace Oocx.TfPlan2Md.HtmlRenderer.Rendering;

/// <summary>
/// Converts Markdown content into HTML fragments using Markdig.
/// Related feature: docs/features/027-markdown-html-rendering/specification.md
/// </summary>
internal sealed class MarkdownToHtmlRenderer
{
    /// <summary>
    /// Matches inline style attributes so GitHub flavor output mirrors platform sanitization rules.
    /// Related feature: docs/features/027-markdown-html-rendering/specification.md
    /// </summary>
    private static readonly Regex StyleRegex = new("(\\s)style\\s*=\\s*\"[^\"]*\"|(\\s)style\\s*=\\s*'[^']*'", RegexOptions.IgnoreCase | RegexOptions.Compiled);

    /// <summary>
    /// Provides the Markdig pipeline instances for rendering.
    /// Related feature: docs/features/027-markdown-html-rendering/specification.md
    /// </summary>
    private readonly MarkdigPipelineFactory _pipelineFactory;

    /// <summary>
    /// Initializes a new instance of the <see cref="MarkdownToHtmlRenderer"/> class.
    /// </summary>
    /// <param name="pipelineFactory">Factory that builds Markdig pipelines per flavor.</param>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="pipelineFactory"/> is null.</exception>
    public MarkdownToHtmlRenderer(MarkdigPipelineFactory pipelineFactory)
    {
        _pipelineFactory = pipelineFactory ?? throw new ArgumentNullException(nameof(pipelineFactory));
    }

    /// <summary>
    /// Renders Markdown into an HTML fragment appropriate for the selected flavor.
    /// </summary>
    /// <param name="markdown">Markdown input to render.</param>
    /// <param name="flavor">Target rendering flavor.</param>
    /// <returns>HTML fragment output.</returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="markdown"/> is null.</exception>
    public string RenderFragment(string markdown, HtmlFlavor flavor)
    {
        ArgumentNullException.ThrowIfNull(markdown);

        var pipeline = _pipelineFactory.Create(flavor);
        var document = Markdown.Parse(markdown, pipeline);
        var html = Markdown.ToHtml(document, pipeline);

        return PostProcess(html, flavor);
    }

    /// <summary>
    /// Strips style attributes from rendered HTML to mimic GitHub sanitization.
    /// </summary>
    /// <param name="html">HTML fragment to sanitize.</param>
    /// <returns>Sanitized HTML without inline style attributes.</returns>
    private static string RemoveStyleAttributes(string html)
    {
        if (string.IsNullOrEmpty(html))
        {
            return html;
        }

        return StyleRegex.Replace(html, match => match.Groups[1].Success ? match.Groups[1].Value : match.Groups[2].Value);
    }

    /// <summary>
    /// Applies flavor-specific post-processing including sanitization and attribute alignment.
    /// Related feature: docs/features/027-markdown-html-rendering/specification.md
    /// </summary>
    /// <param name="html">Rendered HTML fragment.</param>
    /// <param name="flavor">Target flavor.</param>
    /// <returns>Adjusted HTML fragment.</returns>
    private static string PostProcess(string html, HtmlFlavor flavor)
    {
        if (string.IsNullOrEmpty(html))
        {
            return html;
        }

        var withNormalizedBreaks = NormalizeBreakTags(html);
        var withNormalizedRules = NormalizeHorizontalRuleTags(withNormalizedBreaks);
        var withNbsp = ReplaceNonBreakingSpaces(withNormalizedRules);

        if (flavor == HtmlFlavor.GitHub)
        {
            var withDirection = AddDirAuto(withNbsp);
            var withWrappedTables = WrapTablesForGitHub(withDirection);
            var withNotranslate = AddNotranslateToCode(withWrappedTables);
            var withoutIds = RemoveHeadingIds(withNotranslate);
            var withoutStyles = RemoveStyleAttributes(withoutIds);
            return CollapseDanglingTagWhitespace(withoutStyles);
        }

        var withNormalizedDetails = NormalizeDetailsTags(withNbsp);
        var withDiffStyles = NormalizeAzdoDiffInlineStyles(withNormalizedDetails);
        var withTrimmedStyles = TrimTrailingSemicolons(withDiffStyles);
        var withPrefixedIds = RewriteHeadingIdsWithPrefix(withTrimmedStyles, "user-content-");
        return withPrefixedIds;
    }

    /// <summary>
    /// Adds dir="auto" to headings and paragraphs when missing to mirror platform output.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with dir attributes on headings and paragraphs.</returns>
    private static string AddDirAuto(string html)
    {
        return Regex.Replace(html, "<(h[1-6]|p)(?=[\\s>])([^>]*)>", match =>
        {
            var tagName = match.Groups[1].Value;
            var attributes = match.Groups[2].Value;
            if (Regex.IsMatch(attributes, "\\sdir=", RegexOptions.IgnoreCase))
            {
                return match.Value;
            }

            return $"<{tagName} dir=\"auto\"{attributes}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Removes heading id attributes to align with GitHub rendering where ids are absent.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML without heading ids.</returns>
    private static string RemoveHeadingIds(string html)
    {
        return Regex.Replace(html, "<(h[1-6])(.*?)\\sid=\".*?\"(.*?)>", "<$1$2$3>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Prefixes heading id attributes to approximate Azure DevOps / GitHub user-content ids.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <param name="prefix">Prefix to apply to existing ids.</param>
    /// <returns>HTML with prefixed heading ids.</returns>
    private static string RewriteHeadingIdsWithPrefix(string html, string prefix)
    {
        return Regex.Replace(html, "<(h[1-6])([^>]*)>(.*?)</\\1>", match =>
        {
            var tag = match.Groups[1].Value;
            var attributes = match.Groups[2].Value;
            var content = match.Groups[3].Value;
            var slug = CreateSlug(content);
            if (string.IsNullOrEmpty(slug))
            {
                return match.Value;
            }

            var withoutExistingId = Regex.Replace(attributes, "\\sid=\".*?\"", string.Empty, RegexOptions.IgnoreCase | RegexOptions.Compiled);
            return $"<{tag}{withoutExistingId} id=\"{prefix}{slug}\">{content}</{tag}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
    }

    /// <summary>
    /// Replaces non-breaking space characters with HTML entities for clarity and alignment with references.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with explicit &amp;nbsp; entities.</returns>
    private static string ReplaceNonBreakingSpaces(string html)
    {
        return html.Replace("\u00A0", "&nbsp;", StringComparison.Ordinal);
    }

    /// <summary>
    /// Wraps tables with GitHub's accessibility helper and assigns role attributes to mirror recorded output.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with wrapped tables for GitHub fidelity.</returns>
    private static string WrapTablesForGitHub(string html)
    {
        return Regex.Replace(html, "<table(?<attrs>[^>]*)>(?<body>.*?)</table>", match =>
        {
            if (match.Value.Contains("markdown-accessiblity-table", StringComparison.OrdinalIgnoreCase))
            {
                return match.Value;
            }

            var attributes = match.Groups["attrs"].Value;
            if (!Regex.IsMatch(attributes, "\\srole=", RegexOptions.IgnoreCase))
            {
                attributes = $"{attributes} role=\"table\"";
            }

            if (!Regex.IsMatch(attributes, "\\stabindex=", RegexOptions.IgnoreCase))
            {
                attributes = $"{attributes} tabindex=\"0\"";
            }

            return $"<markdown-accessiblity-table data-catalyst=\"\"><table{attributes}>{match.Groups["body"].Value}</table></markdown-accessiblity-table>";
        }, RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
    }

    /// <summary>
    /// Normalizes line break tags to self-closing form for consistent comparisons.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with canonical <br/> tags.</returns>
    private static string NormalizeBreakTags(string html)
    {
        return Regex.Replace(html, "<br\\s*/?>", "<br/>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Normalizes horizontal rule tags to self-closing form for consistent comparisons.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with canonical <hr/> tags.</returns>
    private static string NormalizeHorizontalRuleTags(string html)
    {
        return Regex.Replace(html, "<hr\\s*/?>", "<hr/>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Adds GitHub-style notranslate classes to code elements to mirror platform rendering.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with notranslate applied to code tags.</returns>
    private static string AddNotranslateToCode(string html)
    {
        return Regex.Replace(html, "<code(?<attrs>[^>]*)>", match =>
        {
            var attributes = match.Groups["attrs"].Value;
            if (Regex.IsMatch(attributes, "notranslate", RegexOptions.IgnoreCase))
            {
                return match.Value;
            }

            var classMatch = Regex.Match(attributes, "\\bclass\\s*=\\s*([\"'])(.*?)\\1", RegexOptions.IgnoreCase | RegexOptions.Compiled);
            if (classMatch.Success)
            {
                var beforeClass = attributes[..classMatch.Index];
                var afterClass = attributes[(classMatch.Index + classMatch.Length)..];
                var quote = classMatch.Groups[1].Value;
                var classes = $"{classMatch.Groups[2].Value} notranslate".Trim();
                return $"<code{beforeClass} class={quote}{classes}{quote}{afterClass}>";
            }

            return $"<code class=\"notranslate\"{attributes}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Removes dangling whitespace before tag closures introduced by attribute stripping.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with compact tag delimiters.</returns>
    private static string CollapseDanglingTagWhitespace(string html)
    {
        return Regex.Replace(html, "<(\\w+)\\s+>", "<$1>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Trims trailing semicolons in style attributes to mirror platform normalization.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with trimmed style declarations.</returns>
    private static string TrimTrailingSemicolons(string html)
    {
        return Regex.Replace(html, "style=\"(?<style>[^\"]*?)\"", match =>
        {
            var style = match.Groups["style"].Value.Trim();
            style = style.TrimEnd(';');
            return $"style=\"{style}\"";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Normalizes details tags by trimming trailing style semicolons and removing stray spaces for closer platform output.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with normalized details tags.</returns>
    private static string NormalizeDetailsTags(string html)
    {
        return Regex.Replace(html, "<details(?<attrs>[^>]*)>", match =>
        {
            var attrs = match.Groups["attrs"].Value.Trim();
            if (string.IsNullOrEmpty(attrs))
            {
                return "<details>";
            }

            var normalized = Regex.Replace(attrs, "style=\"(?<style>[^\"]*)\"", styleMatch =>
            {
                var style = styleMatch.Groups["style"].Value.Trim();
                style = style.TrimEnd(';');
                return $"style=\"{style}\"";
            }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

            return $"<details{(normalized.StartsWith(' ') ? string.Empty : " ")}{normalized}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Adds Azure DevOps-like display and whitespace styles to inline diff code and span elements.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with normalized inline diff styles.</returns>
    private static string NormalizeAzdoDiffInlineStyles(string html)
    {
        var withCodeStyles = Regex.Replace(html, "<code\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
        {
            var style = match.Groups["style"].Value;
            style = EnsureStyleDirective(style, "display:block");
            style = EnsureStyleDirective(style, "white-space:normal");
            style = EnsureStyleDirective(style, "padding:0");
            style = EnsureStyleDirective(style, "margin:0");
            return $"<code style=\"{style}\"{match.Groups["rest"].Value}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

        var withSpanStyles = Regex.Replace(withCodeStyles, "<span\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
        {
            var style = match.Groups["style"].Value;
            if (style.Contains("border-left", StringComparison.OrdinalIgnoreCase) || style.Contains("background-color", StringComparison.OrdinalIgnoreCase))
            {
                style = EnsureStyleDirective(style, "display:inline-block");
            }

            return $"<span style=\"{style}\"{match.Groups["rest"].Value}>";
        }, RegexOptions.IgnoreCase | RegexOptions.Compiled);

        return withSpanStyles;
    }

    /// <summary>
    /// Appends a CSS directive to a style string when it is not already present.
    /// </summary>
    /// <param name="style">Existing style string.</param>
    /// <param name="directive">Directive to enforce.</param>
    /// <returns>Updated style string.</returns>
    private static string EnsureStyleDirective(string style, string directive)
    {
        if (string.IsNullOrWhiteSpace(style))
        {
            return directive;
        }

        if (HasStyleDirective(style, directive))
        {
            return style;
        }

        var trimmed = style.Trim();
        return trimmed.EndsWith(';', StringComparison.Ordinal) ? $"{trimmed} {directive}" : $"{trimmed}; {directive}";
    }

    /// <summary>
    /// Determines whether a style attribute already contains the given directive, ignoring whitespace variance.
    /// </summary>
    /// <param name="style">Existing style string.</param>
    /// <param name="directive">Directive to search for.</param>
    /// <returns>True if the directive already exists.</returns>
    private static bool HasStyleDirective(string style, string directive)
    {
        var parts = directive.Split(':', 2);
        if (parts.Length != 2)
        {
            return style.Contains(directive, StringComparison.OrdinalIgnoreCase);
        }

        var property = parts[0].Trim();
        var value = parts[1].Trim();

        if (property.Length == 0 || value.Length == 0)
        {
            return style.Contains(directive, StringComparison.OrdinalIgnoreCase);
        }

        var pattern = $"\\b{Regex.Escape(property)}\\s*:\\s*{Regex.Escape(value)}\\b";
        return Regex.IsMatch(style, pattern, RegexOptions.IgnoreCase | RegexOptions.Compiled);
    }

    /// <summary>
    /// Builds a slug from heading content that preserves emoji and punctuation before prefixing.
    /// </summary>
    /// <param name="headingContent">Inner HTML of the heading.</param>
    /// <returns>URL-encoded slug derived from the heading text.</returns>
    private static string CreateSlug(string headingContent)
    {
        if (string.IsNullOrWhiteSpace(headingContent))
        {
            return string.Empty;
        }

        var withBackticks = Regex.Replace(headingContent, "<code>(.*?)</code>", match => $"`{match.Groups[1].Value}`", RegexOptions.Singleline | RegexOptions.IgnoreCase | RegexOptions.Compiled);
        var withoutTags = Regex.Replace(withBackticks, "<.*?>", string.Empty, RegexOptions.Singleline | RegexOptions.Compiled);
        var decoded = WebUtility.HtmlDecode(withoutTags);
        var trimmed = decoded.Trim();

        if (trimmed.Length == 0)
        {
            return string.Empty;
        }

        var lowered = trimmed.ToLowerInvariant();
        var hyphenated = Regex.Replace(lowered, "\\s+", "-", RegexOptions.Compiled);
        return Uri.EscapeDataString(hyphenated);
    }
}

using System.Net;
using System.Text.RegularExpressions;
using Markdig;

namespace Oocx.TfPlan2Md.HtmlRenderer.Rendering;

/// <summary>
/// Converts Markdown content into HTML fragments using Markdig.
/// Related feature: docs/features/027-markdown-html-rendering/specification.md
/// </summary>
internal sealed class MarkdownToHtmlRenderer
{
