            }

            return $"<markdown-accessiblity-table data-catalyst=\"\"><table{attributes}>{match.Groups["body"].Value}</table></markdown-accessiblity-table>";
        }, RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
    }

    /// <summary>
    /// Normalizes line break tags to self-closing form for consistent comparisons.
    /// </summary>
    /// <param name="html">HTML fragment.</param>
    /// <returns>HTML with canonical <br/> tags.</returns>
    private static string NormalizeBreakTags(string html)
