270      /// <summary>
271      /// Normalizes details tags by trimming trailing style semicolons and removing stray spaces for closer platform output.
272      /// </summary>
273      /// <param name="html">HTML fragment.</param>
274      /// <returns>HTML with normalized details tags.</returns>
275      private static string NormalizeDetailsTags(string html)
276      {
277          return Regex.Replace(html, "<details(?<attrs>[^>]*)>", match =>
278          {
279              var attrs = match.Groups["attrs"].Value.Trim();
280              if (string.IsNullOrEmpty(attrs))
281              {
282                  return "<details>";
283              }
284
285              var normalized = Regex.Replace(attrs, "style=\"(?<style>[^\"]*)\"", styleMatch =>
286              {
287                  var style = styleMatch.Groups["style"].Value.Trim();
288                  style = style.TrimEnd(';');
289                  return $"style=\"{style}\"";
290              }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
291
292              return $"<details{(normalized.StartsWith(' ') ? string.Empty : " ")}{normalized}>";
293          }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
