296      /// <summary>
297      /// Adds Azure DevOps-like display and whitespace styles to inline diff code and span elements.
298      /// </summary>
299      /// <param name="html">HTML fragment.</param>
300      /// <returns>HTML with normalized inline diff styles.</returns>
301      private static string NormalizeAzdoDiffInlineStyles(string html)
302      {
303          var withCodeStyles = Regex.Replace(html, "<code\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
304          {
305              var style = match.Groups["style"].Value;
306              style = EnsureStyleDirective(style, "display:block");
307              style = EnsureStyleDirective(style, "white-space:normal");
308              style = EnsureStyleDirective(style, "padding:0");
309              style = EnsureStyleDirective(style, "margin:0");
310              return $"<code style=\"{style}\"{match.Groups["rest"].Value}>";
311          }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
312
313          var withSpanStyles = Regex.Replace(withCodeStyles, "<span\\s+style=\\\"(?<style>[^\\\"]*)\\\"(?<rest>[^>]*)>", match =>
314          {
315              var style = match.Groups["style"].Value;
316              if (style.Contains("border-left", StringComparison.OrdinalIgnoreCase) || style.Contains("background-color", StringComparison.OrdinalIgnoreCase))
317              {
318                  var hasDisplay = Regex.IsMatch(style, "(^|;\\s*)display\\s*:", RegexOptions.IgnoreCase | RegexOptions.Compiled);
319                  if (!hasDisplay)
320                  {
321                      style = EnsureStyleDirective(style, "display:inline-block");
322                  }
323              }
324
325              return $"<span style=\"{style}\"{match.Groups["rest"].Value}>";
326          }, RegexOptions.IgnoreCase | RegexOptions.Compiled);
327
328          return withSpanStyles;
329      }
