331      /// <summary>
332      /// Appends a CSS directive to a style string when it is not already present.
333      /// </summary>
334      /// <param name="style">Existing style string.</param>
335      /// <param name="directive">Directive to enforce.</param>
336      /// <returns>Updated style string.</returns>
337      private static string EnsureStyleDirective(string style, string directive)
338      {
339          if (string.IsNullOrWhiteSpace(style))
340          {
341              return directive;
342          }
343
344          if (HasStyleDirective(style, directive))
345          {
346              return style;
347          }
348
349          var trimmed = style.Trim();
350          return trimmed.EndsWith(';') ? $"{trimmed} {directive}" : $"{trimmed}; {directive}";
351      }
