353      /// <summary>
354      /// Determines whether a style attribute already contains the given directive, ignoring whitespace variance.
355      /// </summary>
356      /// <param name="style">Existing style string.</param>
357      /// <param name="directive">Directive to search for.</param>
358      /// <returns>True if the directive already exists.</returns>
359      private static bool HasStyleDirective(string style, string directive)
360      {
361          var parts = directive.Split(':', 2);
362          if (parts.Length != 2)
363          {
364              return style.Contains(directive, StringComparison.OrdinalIgnoreCase);
365          }
366
367          var property = parts[0].Trim();
368          var value = parts[1].Trim();
369
370          if (property.Length == 0 || value.Length == 0)
371          {
372              return style.Contains(directive, StringComparison.OrdinalIgnoreCase);
373          }
374
375          var pattern = $"(^|;\\s*){Regex.Escape(property)}\\s*:\\s*{Regex.Escape(value)}(\\s*(;|$))";
376          return Regex.IsMatch(style, pattern, RegexOptions.IgnoreCase | RegexOptions.Compiled);
377      }
